olor: #007700">= </span><span style="color: #DD0000">'bar'</span><span style="color: #007700">;<br><br>echo (new </span><span style="color: #9876AA">\ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'Foo\BAR'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getName</span><span style="color: #007700">();<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Foo\BAR</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-reflectionconstant.getname-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link ReflectionConstant::getNamespaceName()} - Gets namespace name</span></li>  </ul> </div></div>
