/**
 * <div id="reflectionconstant.getnamespacename" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::getNamespaceName</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">ReflectionConstant::getNamespaceName</span> — <span class="dc-title">Gets namespace name</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.getnamespacename-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getNamespaceName</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Gets the namespace name of the constant.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.getnamespacename-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.getnamespacename-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The namespace name, or an empty string for the global namespace.  </p> </div> <div class="refsect1 examples" id="refsect1-reflectionconstant.getnamespacename-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getNamespaceName()</strong></span> example</strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">namespace </span><span style="color: #9876AA">Foo </span><span style="color: #007700">{<br>   const </span><span style="color: #9876AA">BAR </span><span style="color: #007700">= </span><span style="color: #DD0000">'bar'</span><span style="color: #007700">;<br>   </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">\ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'Foo\BAR'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getNamespaceName</span><span style="color: #007700">());<br>}<br><br>namespace {<br>   const </span><span style="color: #9876AA">BAR </span><span style="color: #007700">= </span><span style="color: #DD0000">'bar'</span><span style="color: #007700">;<br>   </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">\ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'BAR'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getNamespaceName</span><span style="color: #007700">());<br>}<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">string(3)&nbsp;"Foo"<br>string(0)&nbsp;""</blockquote></div>   </div>  </div> </div></div>
