76AA">var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">\ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'FOO'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getValue</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">string(3)&nbsp;"foo"</blockquote></div>   </div>  </div> </div></div>
 */
    public function getValue(): mixed {}

/**
 * <div id="reflectionconstant.isdeprecated" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::isDeprecated</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">ReflectionConstant::isDeprecated</span> — <span class="dc-title">Checks if deprecated</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.isdeprecated-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::isDeprecated</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.boolean.php" class="type bool" style="color:#EAB766">bool</a></span></div>  <p class="simpara">   Checks whether the constant is deprecated.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.isdeprecated-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.isdeprecated-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong> if it's deprecated, otherwise <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong>  </p> </div> <div class="refsect1 examples" id="refsect1-reflectionconstant.isdeprecated-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1     <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::isDeprecated()</strong></span> example   </strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #FF8000">// E_STRICT is deprecated as of PHP 8.4<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'E_STRICT'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">isDeprecated</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例在 PHP 8.4 中的输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">bool(true)</blockquote></div>   </div>  </div> </div></div>
 */
    public function isDeprecated(): bool {}

/**
 * <div id="reflectionconstant.tostring" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::__toString</h1>  <p class="verinfo">(PHP 8 &gt;= 8.4.0)</p><p class="refpurpose"><span class="refname">ReflectionConstant::__toString</span> — <span class="dc-title">Returns string representation</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.tostring-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::__toString</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the string representation of the   <span class="classname"><a href="https://php.net/manual/zh/class.reflectionconstant.php" class="classname">ReflectionConstant</a></span> object.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.tostring-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.tostring-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   A string representation of this <span class="classname"><a href="https://php.net/manual/zh/class.reflectionconstant.php" class="classname">ReflectionConstant</a></span> instance.  </p> </div> <div class="refsect1 seealso" id="refsect1-reflectionconstant.tostring-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><a href="https://php.net/manual/zh/language.oop5.magic.php#object.tostring" class="link">__toString()</a></li>  </ul> </div></div>
 */
    public function __toString(): string {}

    /**
 * <div id="reflectionconstant.getfilename" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::getFileName</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">ReflectionConstant::getFileName</span> — <span class="dc-title">Gets name of the defining file</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.getfilename-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getFileName</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.singleton.php" class="type false" style="color:#EAB766">false</a></span></span></div>  <p class="simpara">   Gets the filename of the file in which the constant has been defined.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.getfilename-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.getfilename-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the filename of the file in which the constant has been defined.   If the constant is defined in the PHP core or in a PHP extension,   <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> is returned.  </p> </div></div>
 * 
     * @since 8.5
     */
    public function getFileName(): string|false {}

    /**
 * <div id="reflectionconstant.getextension" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::getExtension</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">ReflectionConstant::getExtension</span> — <span class="dc-title">Gets <span class="classname"><a href="https://php.net/manual/zh/class.reflectionextension.php" class="classname">ReflectionExtension</a></span> of the defining extension</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.getextension-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getExtension</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.reflectionextension.php" class="type ReflectionExtension" style="color:#EAB766">ReflectionExtension</a></span></span></div>  <p class="simpara">   Gets a <span class="classname"><a href="https://php.net/manual/zh/class.reflectionextension.php" class="classname">ReflectionExtension</a></span> object for the extension   which defined the constant.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.getextension-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.getextension-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   A <span class="classname"><a href="https://php.net/manual/zh/class.reflectionextension.php" class="classname">ReflectionExtension</a></span> object representing the   extension which defined the constant, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> for user-defined constants.  </p> </div> <div class="refsect1 examples" id="refsect1-reflectionconstant.getextension-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 Basic usage of <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getExtension()</strong></span></strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'SQLITE3_TEXT'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getExtension</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">object(ReflectionExtension)#2&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["name"]=&gt;<br>&nbsp;&nbsp;string(7)&nbsp;"sqlite3"<br>}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-reflectionconstant.getextension-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link ReflectionConstant::getExtensionName()} - Gets name of the defining extension</span></li>  </ul> </div></div>
 * 
     * @since 8.5
     */
    public function getExtension(): ?ReflectionExtension {}

    /**
 * <div id="reflectionconstant.getextensionname" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::getExtensionName</h1>  <p class="verinfo">(PHP 8 &gt;= 8.5.0)</p><p class="refpurpose"><span class="refname">ReflectionConstant::getExtensionName</span> — <span class="dc-title">Gets name of the defining extension</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.getextensionname-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getExtensionName</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.singleton.php" class="type false" style="color:#EAB766">false</a></span></span></div>  <p class="simpara">   Gets the name of the extension which defined the constant.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.getextensionname-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.getextensionname-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   The name of the extension which defined the constant, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.false">false</a></span></strong> for user-defined constants.  </p> </div> <div class="refsect1 examples" id="refsect1-reflectionconstant.getextensionname-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 Basic usage of <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getExtensionName()</strong></span></strong></p>   <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>var_dump</span><span style="color: #007700">((new </span><span style="color: #9876AA">ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'SQLITE3_TEXT'</span><span style="color: #007700">))-&gt;</span><span style="color: #9876AA">getExtensionName</span><span style="color: #007700">());<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">string(7)&nbsp;"sqlite3"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-reflectionconstant.getextensionname-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link ReflectionConstant::getExtension()} - Gets ReflectionExtension of the defining extension</span></li>  </ul> </div></div>
 * 
     * @since 8.5
     */
    public function getExtensionName(): string|false {}

    /**
 * <div id="reflectionconstant.getattributes" class="refentry"> <div class="refnamediv">  <h1 class="refname">ReflectionConstant::getAttributes</h1>  <p class="verinfo">(No version information available, might only be in Git)</p><p class="refpurpose"><span class="refname">ReflectionConstant::getAttributes</span> — <span class="dc-title">Gets Attributes</span></p> </div> <div class="refsect1 description" id="refsect1-reflectionconstant.getattributes-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>ReflectionConstant::getAttributes</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></span> <span class="parameter" style="color:#3A95FF">\$name</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$flags</span><span class="initializer"> = 0</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Returns all attributes declared on this global constant as an array of <span class="classname"><a href="https://php.net/manual/zh/class.reflectionattribute.php" class="classname">ReflectionAttribute</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-reflectionconstant.getattributes-parameters">  <h3 class="title">参数</h3>  <dl>   <dt><span class="parameter" style="color:#3A95FF">name</span></dt><dd> <span class="simpara">  过滤结果，匹配此类名，仅包含 <span class="classname"><a href="https://php.net/manual/zh/class.reflectionattribute.php" class="classname">ReflectionAttribute</a></span> 实例的属性。 </span></dd>   <dt><span class="parameter" style="color:#3A95FF">flags</span></dt><dd> <span class="simpara">  如果提供了 <span class="parameter" style="color:#3A95FF">name</span>，则用于确定如何过滤结果的 flag。 </span> <span class="simpara">  默认值为 <span class="literal">0</span>，这将导致返回的结果只属于类 <span class="parameter" style="color:#3A95FF">name</span> 的属性。 </span> <span class="simpara">  唯一可用的其他选项是使用 <strong><span>{@link ReflectionAttribute::IS_INSTANCEOF}</span></strong>，它将改为使用 <span class="literal">instanceof</span> 进行过滤。 </span></dd>  </dl> </div> <div class="refsect1 returnvalues" id="refsect1-reflectionconstant.getattributes-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Array of attributes, as <span class="classname"><a href="https://php.net/manual/zh/class.reflectionattribute.php" class="classname">ReflectionAttribute</a></span> objects.  </p> </div> <div class="refsect1 changelog" id="refsect1-reflectionconstant.getattributes-changelog">  <h3 class="title">更新日志</h3>  <p class="para">   </p><table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">      <tr>       <td>8.5.0</td>       <td>        This method was introduced.       </td>      </tr>     </tbody>       </table>   </div> <div class="refsect1 examples" id="refsect1-reflectionconstant.getattributes-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 Basic usage</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">#[</span><span style="color: #9876AA">Attribute</span><span style="color: #007700">]<br>class </span><span style="color: #9876AA">Fruit </span><span style="color: #007700">{<br>}<br><br>#[</span><span style="color: #9876AA">Attribute</span><span style="color: #007700">]<br>class </span><span style="color: #9876AA">Red </span><span style="color: #007700">{<br>}<br><br>#[</span><span style="color: #9876AA">Fruit</span><span style="color: #007700">]<br>#[</span><span style="color: #9876AA">Red</span><span style="color: #007700">]<br>const </span><span style="color: #9876AA">APPLE </span><span style="color: #007700">= </span><span style="color: #DD0000">'apple'</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$constant </span><span style="color: #007700">= new </span><span style="color: #9876AA">ReflectionConstant</span><span style="color: #007700">(</span><span style="color: #DD0000">'APPLE'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$attributes </span><span style="color: #007700">= </span><span style="color: #9876AA">\$constant</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getAttributes</span><span style="color: #007700">();<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(fn(</span><span style="color: #9876AA">\$attribute</span><span style="color: #007700">) =&gt; </span><span style="color: #9876AA">\$attribute</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getName</span><span style="color: #007700">(), </span><span style="color: #9876AA">\$attributes</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Fruit<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Red<br>)</blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-reflectionconstant.getattributes-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link ReflectionClass::getAttributes()} - 获取所有属性</span></li>   <li><span class="methodname" style="color:#CC7832">{@link ReflectionClassConstant::getAttributes()} - Gets Attributes</span></li>   <li><span class="methodname" style="color:#CC7832">{@link ReflectionFunctionAbstract::getAttributes()} - Gets Attributes</span></li>   <li><span class="methodname" style="color:#CC7832">{@link ReflectionProperty::getAttributes()} - Gets Attributes</span></li>  </ul> </div></div>
 * 
     * @since 8.5
     */
    public function getAttributes(?string $name = null, int $flags = 0): array {}

    /**
     * @return bool
     * @since 8.6
     */
    public function inNamespace(): bool {}
}
